-- public.preview_client_order(p_client_account_id uuid, p_start_date date, p_start_time time without time zone, p_end_time time without time zone, p_postcode text, p_grade text, p_activity_tags text[], p_required_tags text[], p_radius_km numeric)
CREATE OR REPLACE FUNCTION public.preview_client_order(p_client_account_id uuid, p_start_date date, p_start_time time without time zone, p_end_time time without time zone, p_postcode text, p_grade text, p_activity_tags text[], p_required_tags text[], p_radius_km numeric)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (r - 'organization_id')
         || jsonb_build_object('info', case when same.sentence is null then '[]'::jsonb
                                            else '["same_order_already_confirmed"]'::jsonb end,
                               'same_order_sentence', same.sentence)
  from private.client_order_check(p_client_account_id, p_start_date, p_start_time, p_end_time, p_postcode, p_grade,
                                  p_activity_tags, p_required_tags, p_radius_km) r
  left join lateral (
    select p.request_title as sentence from public.partner_requests p
    where jsonb_array_length(r -> 'problems') = 0
      and p.client_account_id = p_client_account_id and p.status = 'client_confirmed'
      and p.starts_at = (r ->> 'starts_at')::timestamptz and p.ends_at = (r ->> 'ends_at')::timestamptz
      and p.grade = p_grade and p.postcode = r ->> 'postcode'
    order by p.confirmed_at limit 1) same on true
$function$;

revoke all on function public.preview_client_order(p_client_account_id uuid, p_start_date date, p_start_time time without time zone, p_end_time time without time zone, p_postcode text, p_grade text, p_activity_tags text[], p_required_tags text[], p_radius_km numeric) from public, anon, authenticated, service_role;
grant execute on function public.preview_client_order(p_client_account_id uuid, p_start_date date, p_start_time time without time zone, p_end_time time without time zone, p_postcode text, p_grade text, p_activity_tags text[], p_required_tags text[], p_radius_km numeric) to authenticated;
grant execute on function public.preview_client_order(p_client_account_id uuid, p_start_date date, p_start_time time without time zone, p_end_time time without time zone, p_postcode text, p_grade text, p_activity_tags text[], p_required_tags text[], p_radius_km numeric) to service_role;
